with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (91, 'Do you like your current job?', 'Você gosta do seu trabalho atual?', '[{"answer":"Yes, I do.","translation":"Sim, eu gosto.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, I really enjoy my job.","translation":"Sim, eu gosto muito do meu trabalho.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Most of the time, yes.","translation":"Na maior parte do tempo, sim.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"It''s okay, but I''d like a new challenge.","translation":"É bom, mas eu gostaria de um novo desafio.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like many parts of it, especially the people and the opportunities to learn.","translation":"Eu gosto de muitos aspectos, especialmente das pessoas e das oportunidades de aprender.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (92, 'What is the best thing about your job?', 'Qual é a melhor coisa no seu trabalho?', '[{"answer":"The best thing is the people I work with.","translation":"A melhor coisa são as pessoas com quem trabalho.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I like the flexibility.","translation":"Eu gosto da flexibilidade.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I enjoy solving problems.","translation":"Eu gosto de resolver problemas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"The best part is learning new things.","translation":"A melhor parte é aprender coisas novas.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"What I like most is seeing the results of my work and knowing it was useful.","translation":"O que mais gosto é ver os resultados do meu trabalho e saber que ele foi útil.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (93, 'What do you usually do after work?', 'O que você costuma fazer depois do trabalho?', '[{"answer":"I usually go home and relax.","translation":"Eu geralmente vou para casa e relaxo.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I go to the gym after work.","translation":"Eu vou à academia depois do trabalho.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually have dinner with my family.","translation":"Eu geralmente janto com minha família.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Sometimes I meet friends or run errands.","translation":"Às vezes eu encontro amigos ou resolvo algumas coisas.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"After work, I try to disconnect, have dinner, and do something relaxing.","translation":"Depois do trabalho, eu tento me desligar, jantar e fazer algo relaxante.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (94, 'What is the most difficult thing about your job?', 'Qual é a coisa mais difícil no seu trabalho?', '[{"answer":"The workload can be difficult.","translation":"A carga de trabalho pode ser difícil.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Deadlines are sometimes stressful.","translation":"Prazos às vezes são estressantes.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"The hardest part is dealing with unexpected problems.","translation":"A parte mais difícil é lidar com problemas inesperados.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Communication can be challenging sometimes.","translation":"A comunicação pode ser desafiadora às vezes.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"The most difficult part is balancing several priorities at the same time.","translation":"A parte mais difícil é equilibrar várias prioridades ao mesmo tempo.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (95, 'Would you like to change careers someday?', 'Você gostaria de mudar de carreira algum dia?', '[{"answer":"Yes, maybe someday.","translation":"Sim, talvez algum dia.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"No, I''m happy with my career.","translation":"Não, eu estou feliz com a minha carreira.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d consider changing careers for the right opportunity.","translation":"Eu consideraria mudar de carreira pela oportunidade certa.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I might move into a different area of my field.","translation":"Talvez eu mude para uma área diferente dentro da minha profissão.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m open to a change, but I''d want it to build on the experience I already have.","translation":"Eu estou aberto/a a uma mudança, mas gostaria que ela aproveitasse a experiência que já tenho.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (96, 'What are your plans for the future?', 'Quais são os seus planos para o futuro?', '[{"answer":"I want to keep learning and growing.","translation":"Eu quero continuar aprendendo e evoluindo.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I plan to travel more.","translation":"Eu planejo viajar mais.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I want to advance in my career.","translation":"Eu quero avançar na minha carreira.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''d like to buy a house someday.","translation":"Eu gostaria de comprar uma casa algum dia.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My main plans are to develop professionally, improve my English, and have more time for my family.","translation":"Meus principais planos são me desenvolver profissionalmente, melhorar meu inglês e ter mais tempo para minha família.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (97, 'Where do you see yourself in five years?', 'Onde você se vê daqui a cinco anos?', '[{"answer":"I see myself in a better position at work.","translation":"Eu me vejo em uma posição melhor no trabalho.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I hope to be living in a new city.","translation":"Eu espero estar morando em uma cidade nova.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to have my own business.","translation":"Eu gostaria de ter meu próprio negócio.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I hope to be more fluent in English.","translation":"Eu espero estar mais fluente em inglês.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"In five years, I hope to have grown professionally and built a balanced personal life.","translation":"Daqui a cinco anos, espero ter crescido profissionalmente e construído uma vida pessoal equilibrada.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (98, 'What is one goal you want to achieve?', 'Qual é uma meta que você quer alcançar?', '[{"answer":"I want to become fluent in English.","translation":"Eu quero me tornar fluente em inglês.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I want to save more money.","translation":"Eu quero economizar mais dinheiro.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to finish my degree.","translation":"Eu gostaria de concluir minha graduação.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I want to improve my health.","translation":"Eu quero melhorar minha saúde.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"One important goal is to feel confident using English in professional situations.","translation":"Uma meta importante é me sentir confiante usando inglês em situações profissionais.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (99, 'What is something you want to do this year?', 'O que você quer fazer este ano?', '[{"answer":"I want to travel somewhere new.","translation":"Eu quero viajar para algum lugar novo.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I want to read more books.","translation":"Eu quero ler mais livros.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to start exercising regularly.","translation":"Eu gostaria de começar a me exercitar regularmente.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I want to improve my English.","translation":"Eu quero melhorar meu inglês.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"This year, I want to complete a personal project that I''ve been postponing.","translation":"Este ano, quero concluir um projeto pessoal que venho adiando.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (100, 'If you could learn any skill, what would you choose?', 'Se você pudesse aprender qualquer habilidade, qual escolheria?', '[{"answer":"I''d learn to play the piano.","translation":"Eu aprenderia a tocar piano.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d choose public speaking.","translation":"Eu escolheria falar em público.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d learn another language.","translation":"Eu aprenderia outro idioma.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''d like to learn how to code.","translation":"Eu gostaria de aprender a programar.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d choose a skill that combines creativity and technology, like design.","translation":"Eu escolheria uma habilidade que combinasse criatividade e tecnologia, como design.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions q set question_text=c.question_text,question_translation=c.question_translation,answer_examples=c.answer_examples from card_content c where q.display_order=c.display_order;
